'use strict';

var Axis = require( '@stdlib/plot/vega/axis/ctor' );
var isAxis = require( './../lib' );

var v = new Axis({
	'scale': 'xScale',
	'orient': 'bottom'
});
var bool = isAxis( v );
console.log( bool );
// => true

bool = isAxis( {} );
console.log( bool );
// => false

bool = isAxis( 'foo' );
console.log( bool );
// => false
